import heapq


def maxStackOps(ops):
    stack = []        # (value, id)
    heap = []         # (-value, -id)
    removed = set()
    out = []
    uid = 0
    for t, x in ops:
        if t == 0:
            uid += 1
            stack.append((x, uid))
            heapq.heappush(heap, (-x, -uid))
            continue
        while stack and stack[-1][1] in removed:
            stack.pop()
        while heap and -heap[0][1] in removed:
            heapq.heappop(heap)
        if t == 1:
            v, i = stack.pop()
            removed.add(i)
            out.append(v)
        elif t == 2:
            out.append(stack[-1][0])
        elif t == 3:
            out.append(-heap[0][0])
        else:
            nv, ni = heapq.heappop(heap)
            removed.add(-ni)
            out.append(-nv)
    return out
